package com.fctvclean.diag;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.*;import android.os.*;import android.provider.*;import android.widget.*;
public class MainActivity extends Activity{TextView v;public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);v=new TextView(this);v.setText("DIAG C — REQUEST_INSTALL_PACKAGES + PackageInstaller\n\nNon modifica né firma APK. Il pulsante apre soltanto la pagina Android per autorizzare questa app come sorgente di installazione.");Button x=new Button(this);x.setText("Apri autorizzazione installazione");x.setOnClickListener(q->{if(Build.VERSION.SDK_INT>=26)startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));});l.addView(v);l.addView(x);setContentView(l);PackageInstaller pi=getPackageManager().getPackageInstaller();v.append("\n\nPackageInstaller disponibile: "+(pi!=null));}}
